interface Server { id: string; healthy: boolean; active: number }

interface Strategy {
  pick(servers: Server[], key?: string): Server | null;
}

class RoundRobin implements Strategy {
  private next = 0;
  pick(servers: Server[]): Server | null {
    if (servers.length === 0) return null;
    const s = servers[this.next % servers.length];
    this.next = (this.next + 1) % servers.length; // wrap, never overflow
    return s;
  }
}

class LeastConnections implements Strategy {
  pick(servers: Server[]): Server | null {
    return servers.reduce<Server | null>((best, s) => (best === null || s.active < best.active ? s : best), null);
  }
}

class LoadBalancer {
  private servers = new Map<string, Server>();
  constructor(private strategy: Strategy) {}

  addServer(id: string) { this.servers.set(id, { id, healthy: true, active: 0 }); }
  removeServer(id: string) { this.servers.delete(id); }
  setHealth(id: string, healthy: boolean) { const s = this.servers.get(id); if (s) s.healthy = healthy; }
  setStrategy(strategy: Strategy) { this.strategy = strategy; }

  route(key?: string): Server {
    const healthy = [...this.servers.values()].filter((s) => s.healthy);
    const chosen = this.strategy.pick(healthy, key);
    if (!chosen) throw new Error('no healthy servers');
    chosen.active++;
    return chosen; // caller calls release(chosen) when the request finishes
  }
  release(s: Server) { s.active = Math.max(0, s.active - 1); }
}

from abc import ABC, abstractmethod
from dataclasses import dataclass

@dataclass
class Server:
    id: str
    healthy: bool = True
    active: int = 0

class Strategy(ABC):
    @abstractmethod
    def pick(self, servers, key=None): ...

class RoundRobin(Strategy):
    def __init__(self):
        self._next = 0
    def pick(self, servers, key=None):
        if not servers:
            return None
        s = servers[self._next % len(servers)]
        self._next = (self._next + 1) % len(servers)
        return s

class LeastConnections(Strategy):
    def pick(self, servers, key=None):
        return min(servers, key=lambda s: s.active, default=None)

class LoadBalancer:
    def __init__(self, strategy: Strategy):
        self._servers: dict[str, Server] = {}
        self._strategy = strategy

    def add_server(self, id): self._servers[id] = Server(id)
    def remove_server(self, id): self._servers.pop(id, None)
    def set_health(self, id, healthy):
        if id in self._servers: self._servers[id].healthy = healthy

    def route(self, key=None) -> Server:
        healthy = [s for s in self._servers.values() if s.healthy]
        chosen = self._strategy.pick(healthy, key)
        if chosen is None:
            raise RuntimeError('no healthy servers')
        chosen.active += 1
        return chosen

interface Strategy { Server pick(List<Server> servers, String key); }

class RoundRobin implements Strategy {
    private final AtomicInteger next = new AtomicInteger();
    public Server pick(List<Server> servers, String key) {
        if (servers.isEmpty()) return null;
        int i = Math.floorMod(next.getAndIncrement(), servers.size());
        return servers.get(i);
    }
}

class LoadBalancer {
    private final Map<String, Server> servers = new ConcurrentHashMap<>();
    private volatile Strategy strategy;
    LoadBalancer(Strategy s) { this.strategy = s; }

    Server route(String key) {
        List<Server> healthy = servers.values().stream().filter(Server::isHealthy).toList();
        Server chosen = strategy.pick(healthy, key);
        if (chosen == null) throw new IllegalStateException("no healthy servers");
        return chosen;
    }
}

struct Server { std::string id; bool healthy = true; int active = 0; };

struct Strategy {
    virtual ~Strategy() = default;
    virtual Server* pick(std::vector<Server*>& servers, const std::string& key) = 0;
};

struct RoundRobin : Strategy {
    std::atomic<size_t> next{0};
    Server* pick(std::vector<Server*>& servers, const std::string&) override {
        if (servers.empty()) return nullptr;
        return servers[next.fetch_add(1) % servers.size()];
    }
};

class Node {
  constructor(key, value) { this.key = key; this.value = value; this.prev = null; this.next = null; }
}

class LRUCache {
  constructor(capacity) {
    this.capacity = capacity;
    this.map = new Map();
    this.head = new Node(0, 0); // most recent side
    this.tail = new Node(0, 0); // least recent side
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }
  #remove(n) { n.prev.next = n.next; n.next.prev = n.prev; }
  #addFront(n) {
    n.next = this.head.next; n.prev = this.head;
    this.head.next.prev = n; this.head.next = n;
  }
  get(key) {
    const n = this.map.get(key);
    if (!n) return -1;
    this.#remove(n); this.#addFront(n);
    return n.value;
  }
  put(key, value) {
    const existing = this.map.get(key);
    if (existing) { existing.value = value; this.#remove(existing); this.#addFront(existing); return; }
    if (this.map.size === this.capacity) {
      const lru = this.tail.prev;
      this.#remove(lru); this.map.delete(lru.key);
    }
    const n = new Node(key, value);
    this.map.set(key, n); this.#addFront(n);
  }
}

from collections import OrderedDict

# Idiomatic: OrderedDict keeps insertion order and can move keys to the end in O(1)
class LRUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.data = OrderedDict()

    def get(self, key):
        if key not in self.data:
            return -1
        self.data.move_to_end(key)          # mark most recent
        return self.data[key]

    def put(self, key, value):
        if key in self.data:
            self.data.move_to_end(key)
        self.data[key] = value
        if len(self.data) > self.capacity:
            self.data.popitem(last=False)   # evict least recent

# In an interview, also be ready to write the hash map + doubly linked list version by hand.

class LRUCache<K, V> {
    private final int capacity;
    private final LinkedHashMap<K, V> map;

    LRUCache(int capacity) {
        this.capacity = capacity;
        // accessOrder = true makes get() move the entry to the end (most recent)
        this.map = new LinkedHashMap<>(16, 0.75f, true) {
            @Override protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
                return size() > LRUCache.this.capacity;
            }
        };
    }
    synchronized V get(K key) { return map.get(key); }
    synchronized void put(K key, V value) { map.put(key, value); }
}

class LRUCache {
    int cap;
    list<pair<int,int>> items;                       // front = most recent
    unordered_map<int, list<pair<int,int>>::iterator> pos;
public:
    LRUCache(int c) : cap(c) {}
    int get(int key) {
        auto it = pos.find(key);
        if (it == pos.end()) return -1;
        items.splice(items.begin(), items, it->second); // move to front, O(1)
        return it->second->second;
    }
    void put(int key, int value) {
        auto it = pos.find(key);
        if (it != pos.end()) { it->second->second = value; items.splice(items.begin(), items, it->second); return; }
        if ((int)items.size() == cap) { pos.erase(items.back().first); items.pop_back(); }
        items.emplace_front(key, value);
        pos[key] = items.begin();
    }
};

interface RateLimiter { allow(key: string): boolean }

type Clock = () => number; // milliseconds

class TokenBucketLimiter implements RateLimiter {
  private buckets = new Map<string, { tokens: number; last: number }>();

  constructor(
    private capacity: number,
    private refillPerSec: number,
    private now: Clock = Date.now, // injectable for tests
  ) {}

  allow(key: string): boolean {
    const t = this.now();
    const b = this.buckets.get(key) ?? { tokens: this.capacity, last: t };
    const elapsedSec = Math.max(0, (t - b.last) / 1000); // clamp if the clock goes backwards
    b.tokens = Math.min(this.capacity, b.tokens + elapsedSec * this.refillPerSec);
    b.last = t;
    this.buckets.set(key, b);
    if (b.tokens >= 1) {
      b.tokens -= 1;
      return true;
    }
    return false;
  }
}

// 5 requests burst, 1 per second sustained
const limiter = new TokenBucketLimiter(5, 1);

class TokenBucketLimiter {
    private static class Bucket { double tokens; long last; }
    private final ConcurrentHashMap<String, Bucket> buckets = new ConcurrentHashMap<>();
    private final double capacity, ratePerSec;

    TokenBucketLimiter(double capacity, double ratePerSec) { this.capacity = capacity; this.ratePerSec = ratePerSec; }

    boolean allow(String key) {
        long now = System.nanoTime();
        Bucket b = buckets.computeIfAbsent(key, k -> { Bucket x = new Bucket(); x.tokens = capacity; x.last = now; return x; });
        synchronized (b) { // per-key lock, not a global one
            double elapsedSec = Math.max(0, (now - b.last) / 1e9);
            b.tokens = Math.min(capacity, b.tokens + elapsedSec * ratePerSec);
            b.last = now;
            if (b.tokens >= 1) { b.tokens -= 1; return true; }
            return false;
        }
    }
}

class TokenBucket {
    double capacity, rate, tokens;
    std::chrono::steady_clock::time_point last;
    std::mutex mu;
public:
    TokenBucket(double cap, double perSec) : capacity(cap), rate(perSec), tokens(cap), last(std::chrono::steady_clock::now()) {}
    bool allow() {
        std::lock_guard<std::mutex> g(mu);
        auto now = std::chrono::steady_clock::now();
        double elapsed = std::chrono::duration<double>(now - last).count();
        tokens = std::min(capacity, tokens + elapsed * rate);
        last = now;
        if (tokens >= 1) { tokens -= 1; return true; }
        return false;
    }
};
